import base64,json,pathlib,tempfile,subprocess,sys,shlex
files=json.loads(base64.b64decode(''))
commands=[('ffmpeg -version', 0), ('python setup37.py', 0), ('python setup37.py', 1), ('ffmpeg -n -hide_banner -nostats -v error -f lavfi -i testsrc=duration=3:size=640x360:rate=24 -f lavfi -i sine=frequency=1000:duration=3 -map 0:v:0 -map 1:a:0 -c:v libx264 -threads 1 -crf 18 -pix_fmt yuv420p -c:a aac -b:a 64k -shortest sample/input.mp4', 0), ('python check37.py snapshot', 0), ('ffmpeg -n -hide_banner -nostats -v error -i sample/input.mp4 -map 0:v:0 -map 0:a:0 -c:v libx264 -threads 1 -crf 28 -pix_fmt yuv420p -c:a aac -b:a 64k sample/small.mp4', 0), ('ffprobe -v error -show_entries stream=codec_type,codec_name,pix_fmt:format=duration,size -of json sample/small.mp4', 0), ('python check37.py verify', 0), ('ffmpeg -n -hide_banner -nostats -v error -i sample/input.mp4 -map 0:v:0 -map 0:a:0 -c:v libx264 -threads 1 -crf 28 -pix_fmt yuv420p -c:a aac -b:a 64k sample/small.mp4', -1), ('python check37.py verify', 0), ('ffmpeg -n -hide_banner -nostats -v error -i sample/input.mp4 -vn -c:a copy sample/audio.aac', 0), ('python -c "from pathlib import Path; [print(p.name, p.stat().st_size) for p in sorted(Path(\'sample\').iterdir())]"', 0), ('python -m unittest -v', 0)]
with tempfile.TemporaryDirectory(prefix='lesson37-record-') as d:
 root=pathlib.Path(d)
 for name,text in files.items():(root/name).write_text(text,encoding='utf-8')
 for command,expected in commands:
  print('\n### CMD: '+command,flush=True)
  args=shlex.split(command)
  if args[0]=='python':args[0]=sys.executable
  before=None
  if expected==-1:
   p=root/'sample'/'small.mp4';before=(p.read_bytes(),p.stat().st_mtime_ns)
  result=subprocess.run(args,cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace')
  print(result.stdout,end='',flush=True);print('### EXIT: '+str(result.returncode),flush=True)
  if expected==-1:
   assert 'already exists' in result.stdout and before==(p.read_bytes(),p.stat().st_mtime_ns), 'Refusal did not preserve output'
  elif (result.returncode!=0) != (expected!=0):raise SystemExit('Unexpected exit')
